namespace Payments;

public interface IPaymentProvider
{
    Task<ChargeResult> ChargeAsync(string cardToken, decimal amount, CancellationToken cancellationToken = default);
    Task<RefundResult> RefundAsync(string chargeId, CancellationToken cancellationToken = default);
}

public sealed class PaymentGateway
{
    private readonly IPaymentProvider _provider;
    private readonly Dictionary<string, ChargeRecord> _charges = new();

    public PaymentGateway(IPaymentProvider provider)
    {
        ArgumentNullException.ThrowIfNull(provider);
        _provider = provider;
    }

    public async Task<ChargeResult> ChargeAsync(string cardToken, decimal amount, CancellationToken cancellationToken = default)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(cardToken);

        if (amount <= 0)
            throw new ArgumentOutOfRangeException(nameof(amount), "Charge amount must be positive.");

        if (amount > 999_999.99m)
            throw new ArgumentOutOfRangeException(nameof(amount), "Charge amount exceeds maximum allowed.");

        var result = await _provider.ChargeAsync(cardToken, amount, cancellationToken);

        if (result.Success)
        {
            _charges[result.ChargeId] = new ChargeRecord(result.ChargeId, cardToken, amount, Refunded: false);
        }

        return result;
    }

    public async Task<RefundResult> RefundAsync(string chargeId, CancellationToken cancellationToken = default)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(chargeId);

        if (!_charges.TryGetValue(chargeId, out var charge))
            throw new InvalidOperationException($"Charge '{chargeId}' not found.");

        if (charge.Refunded)
            throw new InvalidOperationException($"Charge '{chargeId}' has already been refunded.");

        var result = await _provider.RefundAsync(chargeId, cancellationToken);

        if (result.Success)
        {
            _charges[chargeId] = charge with { Refunded = true };
        }

        return result;
    }

    public WebhookResult ProcessWebhook(string eventType, string payload)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(eventType);
        ArgumentException.ThrowIfNullOrWhiteSpace(payload);

        return eventType switch
        {
            "charge.succeeded" => new WebhookResult(Handled: true, eventType),
            "charge.failed" => new WebhookResult(Handled: true, eventType),
            "refund.succeeded" => new WebhookResult(Handled: true, eventType),
            _ => new WebhookResult(Handled: false, eventType),
        };
    }
}

public record ChargeResult(string ChargeId, bool Success);
public record RefundResult(string RefundId, bool Success);
public record WebhookResult(bool Handled, string EventType);
internal record ChargeRecord(string ChargeId, string CardToken, decimal Amount, bool Refunded);

