using Payments;

namespace PaymentGateway.Tests;

internal sealed class FakePaymentProvider : IPaymentProvider
{
    private int _chargeCounter;
    private int _refundCounter;

    public bool ShouldSucceed { get; set; } = true;
    public bool ShouldThrow { get; set; }
    public TimeSpan Delay { get; set; } = TimeSpan.Zero;

    public async Task<ChargeResult> ChargeAsync(string cardToken, decimal amount, CancellationToken cancellationToken = default)
    {
        if (ShouldThrow)
            throw new InvalidOperationException("Provider unavailable");

        if (Delay > TimeSpan.Zero)
            await Task.Delay(Delay, cancellationToken);

        var id = $"ch_{Interlocked.Increment(ref _chargeCounter)}";
        return new ChargeResult(id, ShouldSucceed);
    }

    public async Task<RefundResult> RefundAsync(string chargeId, CancellationToken cancellationToken = default)
    {
        if (ShouldThrow)
            throw new InvalidOperationException("Provider unavailable");

        if (Delay > TimeSpan.Zero)
            await Task.Delay(Delay, cancellationToken);

        var id = $"re_{Interlocked.Increment(ref _refundCounter)}";
        return new RefundResult(id, ShouldSucceed);
    }
}

