using Payments;

namespace PaymentGateway.Tests;

[TestClass]
public sealed class PaymentGatewayChargeTests
{
    private readonly FakePaymentProvider _provider;
    private readonly Payments.PaymentGateway _gateway;

    public PaymentGatewayChargeTests()
    {
        _provider = new FakePaymentProvider();
        _gateway = new Payments.PaymentGateway(_provider);
    }

    // --- Happy-path ---

    [TestMethod]
    public async Task ChargeAsync_ValidTokenAndAmount_ReturnsSuccess()
    {
        var result = await _gateway.ChargeAsync("tok_valid", 50.00m);

        Assert.IsTrue(result.Success);
        Assert.IsNotNull(result.ChargeId);
    }

    [TestMethod]
    [DataRow(0.01)]
    [DataRow(1.00)]
    [DataRow(999_999.99)]
    public async Task ChargeAsync_BoundaryAmounts_Succeeds(double amount)
    {
        var result = await _gateway.ChargeAsync("tok_valid", (decimal)amount);

        Assert.IsTrue(result.Success);
    }

    [TestMethod]
    public async Task ChargeAsync_ProviderDeclines_ReturnsFailure()
    {
        _provider.ShouldSucceed = false;

        var result = await _gateway.ChargeAsync("tok_declined", 25.00m);

        Assert.IsFalse(result.Success);
    }

    [TestMethod]
    public async Task ChargeAsync_MultipleCharges_ReturnsUniqueIds()
    {
        var result1 = await _gateway.ChargeAsync("tok_a", 10m);
        var result2 = await _gateway.ChargeAsync("tok_b", 20m);

        Assert.AreNotEqual(result1.ChargeId, result2.ChargeId);
    }

    // --- Validation ---

    [TestMethod]
    public async Task ChargeAsync_NullToken_ThrowsArgumentException()
    {
        await Assert.ThrowsExactlyAsync<ArgumentException>(
            async () => await _gateway.ChargeAsync(null!, 10m));
    }

    [TestMethod]
    [DataRow("")]
    [DataRow("   ")]
    public async Task ChargeAsync_EmptyOrWhitespaceToken_ThrowsArgumentException(string token)
    {
        await Assert.ThrowsExactlyAsync<ArgumentException>(
            async () => await _gateway.ChargeAsync(token, 10m));
    }

    [TestMethod]
    [DataRow(0.0)]
    [DataRow(-1.0)]
    [DataRow(-0.01)]
    public async Task ChargeAsync_ZeroOrNegativeAmount_ThrowsArgumentOutOfRange(double amount)
    {
        await Assert.ThrowsExactlyAsync<ArgumentOutOfRangeException>(
            async () => await _gateway.ChargeAsync("tok_valid", (decimal)amount));
    }

    [TestMethod]
    public async Task ChargeAsync_ExceedsMaxAmount_ThrowsArgumentOutOfRange()
    {
        await Assert.ThrowsExactlyAsync<ArgumentOutOfRangeException>(
            async () => await _gateway.ChargeAsync("tok_valid", 1_000_000.00m));
    }

    // --- Provider errors ---

    [TestMethod]
    public async Task ChargeAsync_ProviderThrows_PropagatesException()
    {
        _provider.ShouldThrow = true;

        await Assert.ThrowsExactlyAsync<InvalidOperationException>(
            async () => await _gateway.ChargeAsync("tok_valid", 10m));
    }

    // --- Cancellation ---

    [TestMethod]
    public async Task ChargeAsync_CancelledToken_ThrowsOperationCanceled()
    {
        _provider.Delay = TimeSpan.FromSeconds(5);
        using var cts = new CancellationTokenSource();
        await cts.CancelAsync();

        await Assert.ThrowsExactlyAsync<TaskCanceledException>(
            async () => await _gateway.ChargeAsync("tok_valid", 10m, cts.Token));
    }
}

