using Payments;

namespace PaymentGateway.Tests;

[TestClass]
public sealed class PaymentGatewayRefundTests
{
    private readonly FakePaymentProvider _provider;
    private readonly Payments.PaymentGateway _gateway;

    public PaymentGatewayRefundTests()
    {
        _provider = new FakePaymentProvider();
        _gateway = new Payments.PaymentGateway(_provider);
    }

    private async Task<string> CreateChargeAsync(decimal amount = 50m)
    {
        var charge = await _gateway.ChargeAsync("tok_valid", amount);
        return charge.ChargeId;
    }

    // --- Happy-path ---

    [TestMethod]
    public async Task RefundAsync_ValidCharge_ReturnsSuccess()
    {
        var chargeId = await CreateChargeAsync();

        var result = await _gateway.RefundAsync(chargeId);

        Assert.IsTrue(result.Success);
        Assert.IsNotNull(result.RefundId);
    }

    [TestMethod]
    public async Task RefundAsync_ProviderDeclines_ReturnsFailureAndAllowsRetry()
    {
        var chargeId = await CreateChargeAsync();
        _provider.ShouldSucceed = false;

        var failed = await _gateway.RefundAsync(chargeId);
        Assert.IsFalse(failed.Success);

        // Retry should be allowed since the first attempt failed
        _provider.ShouldSucceed = true;
        var retried = await _gateway.RefundAsync(chargeId);
        Assert.IsTrue(retried.Success);
    }

    // --- Validation ---

    [TestMethod]
    public async Task RefundAsync_NullChargeId_ThrowsArgumentException()
    {
        await Assert.ThrowsExactlyAsync<ArgumentException>(
            async () => await _gateway.RefundAsync(null!));
    }

    [TestMethod]
    [DataRow("")]
    [DataRow("   ")]
    public async Task RefundAsync_EmptyOrWhitespaceChargeId_ThrowsArgumentException(string chargeId)
    {
        await Assert.ThrowsExactlyAsync<ArgumentException>(
            async () => await _gateway.RefundAsync(chargeId));
    }

    [TestMethod]
    public async Task RefundAsync_UnknownChargeId_ThrowsInvalidOperation()
    {
        var ex = await Assert.ThrowsExactlyAsync<InvalidOperationException>(
            async () => await _gateway.RefundAsync("ch_nonexistent"));

        Assert.Contains("ch_nonexistent", ex.Message);
    }

    // --- Double-refund ---

    [TestMethod]
    public async Task RefundAsync_AlreadyRefunded_ThrowsInvalidOperation()
    {
        var chargeId = await CreateChargeAsync();
        await _gateway.RefundAsync(chargeId);

        var ex = await Assert.ThrowsExactlyAsync<InvalidOperationException>(
            async () => await _gateway.RefundAsync(chargeId));

        Assert.Contains("already been refunded", ex.Message);
    }

    // --- Declined charge cannot be refunded ---

    [TestMethod]
    public async Task RefundAsync_DeclinedCharge_ThrowsInvalidOperation()
    {
        _provider.ShouldSucceed = false;
        var charge = await _gateway.ChargeAsync("tok_declined", 10m);
        Assert.IsFalse(charge.Success);

        // Declined charges are not tracked, so refund should fail
        await Assert.ThrowsExactlyAsync<InvalidOperationException>(
            async () => await _gateway.RefundAsync(charge.ChargeId));
    }

    // --- Provider errors ---

    [TestMethod]
    public async Task RefundAsync_ProviderThrows_PropagatesException()
    {
        var chargeId = await CreateChargeAsync();
        _provider.ShouldThrow = true;

        await Assert.ThrowsExactlyAsync<InvalidOperationException>(
            async () => await _gateway.RefundAsync(chargeId));
    }

    // --- Cancellation ---

    [TestMethod]
    public async Task RefundAsync_CancelledToken_ThrowsOperationCanceled()
    {
        var chargeId = await CreateChargeAsync();
        _provider.Delay = TimeSpan.FromSeconds(5);
        using var cts = new CancellationTokenSource();
        await cts.CancelAsync();

        await Assert.ThrowsExactlyAsync<TaskCanceledException>(
            async () => await _gateway.RefundAsync(chargeId, cts.Token));
    }
}

